S['CH1811TL'] = [{'k': 'noti', 'ch': 'Mở đầu', 'cap': ('THÁI LAN TỪNG TĂNG 13,3%', 'GIỜ KẸT Ở 2%'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '21:15', 'ngay': 'Thứ Ba', 'items': [('Tin tức', 'IMF tháng 10', 'Năm 2026: Việt Nam tăng 8,4%, Thái Lan 2,1%', (34, 197, 94)), ('Zalo', 'Somchai', 'Hồi bố tôi còn trẻ, Thái Lan cũng tăng 13% một năm đấy', (255, 196, 0)), ('Zalo', 'Somchai', 'Rồi cả nhà tôi mất gần hết trong một năm', (239, 68, 68))]}, 'say': 'Năm một nghìn chín trăm tám mươi tám, Thái Lan tăng trưởng mười ba phẩy ba phần trăm. Gần bốn mươi năm sau, họ vẫn chưa thành nước giàu. Tối nay anh Hưng, kỹ sư một nhà máy Nhật ở Bình Dương, đọc tin: năm nay Việt Nam được dự báo tăng tám phẩy bốn phần trăm, Thái Lan chỉ hai phẩy một phần trăm. Anh gửi tin cho Somchai, người bạn Thái học cùng khóa đào tạo. Somchai trả lời: hồi bố anh ấy còn trẻ, Thái Lan cũng tăng như vậy. Rồi cả nhà mất gần hết chỉ trong một năm.'}, {'k': 'bignum', 'anh': 'File:Bangkok_Skyline_from_Movenpick_Hotel,_Asok,_Bangkok_at_night.jpg', 'cap': ('NHANH HƠN CẢ VIỆT NAM', 'RỒI KẸT GẦN 40 NĂM'), 'cols': ((255, 255, 255), (239, 68, 68)), 'value': 13.3, 'fmt': '{:,.1f}', 'unit': '%', 'top': 'THÁI LAN NĂM 1988', 'sub': 'Nay còn khoảng 2% mỗi năm', 'col': (239, 68, 68), 'say': 'Mười ba phẩy ba phần trăm. Nhanh hơn cả Việt Nam bây giờ. Vậy mà đến hôm nay, Thái Lan vẫn đứng ngoài cửa nhóm nước thu nhập cao, tăng trưởng chỉ còn khoảng hai phần trăm, các gia đình Thái gánh khoản nợ gần chín mươi phần trăm GDP. Việt Nam sẽ thành Hàn Quốc, hay thành Thái Lan thứ hai? Và chuyện đó liên quan gì tới túi tiền nhà mình?'}, {'k': 'cards', 'ch': 'Chương 1 – Con hổ từng chạy nhanh nhất châu Á', 'anh': 'File:Bangkok_-_City_skyline_at_sunset.JPG', 'cap': ('THÁI LAN THỜI HOÀNG KIM', 'TIỀN PHONG, SỐ NGÂN HÀNG THẾ GIỚI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('+13,3%', 'GDP Thái Lan năm 1988', 'Cao nhất thời hoàng kim'), ('Trên 10%', 'Liên tục từ 1987 tới 1990', 'Bốn năm hai chữ số'), ('7.690 USD', 'Thu nhập mỗi người năm 2025', 'Vẫn chưa thành nước giàu')], 'say': 'Cuối những năm tám mươi, Thái Lan là ngôi sao của châu Á. Theo số Ngân hàng Thế giới mà báo Tiền Phong tổng hợp, từ năm một nghìn chín trăm tám mươi bảy đến năm một nghìn chín trăm chín mươi, kinh tế Thái tăng trên mười phần trăm liên tục. Đỉnh là mười ba phẩy ba phần trăm vào năm một nghìn chín trăm tám mươi tám. Nhà máy Nhật đổ vào Bangkok, giống nhà máy nước ngoài đổ vào Bắc Ninh, Bình Dương bây giờ. Thế nhưng năm hai nghìn không trăm hai mươi lăm, thu nhập bình quân mỗi người Thái mới khoảng bảy nghìn sáu trăm chín mươi đô la.'}, {'k': 'cards', 'anh': 'File:Bangkok_-_City_skyline_at_sunset.JPG', 'cap': ('THÁI LAN THỜI HOÀNG KIM', 'TIỀN PHONG, SỐ NGÂN HÀNG THẾ GIỚI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'cards': [('+13,3%', 'GDP Thái Lan năm 1988', 'Cao nhất thời hoàng kim'), ('Trên 10%', 'Liên tục từ 1987 tới 1990', 'Bốn năm hai chữ số'), ('7.690 USD', 'Thu nhập mỗi người năm 2025', 'Vẫn chưa thành nước giàu')], 'say': 'Ngưỡng nước giàu là mười bốn nghìn ba trăm bảy mươi lăm đô la. Họ mới đi được hơn nửa đường.'}, {'k': 'bars', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('THU NHẬP MỖI NGƯỜI 2025', 'THÁI LAN HƠN 55%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'bars': [('Việt Nam', 4970, (255, 196, 0), '4.970 USD'), ('Thái Lan', 7690, (34, 197, 94), '7.690 USD'), ('Ngưỡng nước giàu', 14375, (239, 68, 68), '14.375 USD')], 'say': 'Còn Việt Nam? Năm hai nghìn không trăm hai mươi lăm, thu nhập bình quân mỗi người Việt khoảng bốn nghìn chín trăm bảy mươi đô la, vừa bước vào nhóm thu nhập trung bình cao. Thái Lan vẫn cao hơn khoảng năm mươi lăm phần trăm, em tự tính. Việt Nam đang đứng gần chỗ Thái Lan từng đứng, và đang chạy nhanh như Thái Lan thời hoàng kim.'}, {'k': 'chat', 'cap': ('"LƯƠNG TÔI GẤP RƯỠI ÔNG', 'MÀ THÁNG NÀO CŨNG HẾT"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Somchai', 'tv': 'Đang hoạt động', 'gio': '21:30', 'mau': (56, 189, 248), 'msgs': [('me', 'Nghe nói lương bên ông cao hơn bên tôi nhiều'), ('Somchai', 'Gấp rưỡi ông đấy, nhưng tháng nào cũng hết sạch'), ('Somchai', 'Xe trả góp, thẻ tín dụng, rồi gửi về cho bố mẹ')]}, 'say': 'Anh Hưng hỏi đùa: nghe nói lương bên đó cao hơn nhiều. Somchai trả lời: gấp rưỡi đấy, nhưng tháng nào cũng hết sạch. Xe trả góp, thẻ tín dụng, rồi gửi về cho bố mẹ. Một đất nước giàu hơn, lương cao hơn, sao người trẻ lại kẹt như vậy? Để hiểu, phải quay lại năm một nghìn chín trăm chín mươi bảy.'}, {'k': 'giay', 'ch': 'Chương 2 – Ngày 2 tháng 7 năm 1997', 'cap': ('NGÀY BAHT BỊ THẢ NỔI', 'MẤT MỘT NỬA GIÁ TRỊ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'NHỮNG CON SỐ CỦA CÚ SẬP 1997', 'so': 'Tổng hợp: Ngân hàng Trung ương Úc 1998, Tiền Phong 2026', 'dau': 'ĐÃ XẢY RA', 'dieu': [('2/7/1997: Thái Lan thả nổi đồng baht', '2/7/1997'), ('Tới tháng 1/1998: baht mất khoảng một nửa', 'MẤT 1/2'), ('Cổ phiếu giảm hơn 60% từ đỉnh đầu 1994', 'HƠN 60%'), ('GDP năm 1998 so với năm trước', 'GIẢM 7,6%')]}, 'say': 'Ngày hai tháng bảy năm một nghìn chín trăm chín mươi bảy, Thái Lan buộc phải thả nổi đồng baht. Theo nghiên cứu của Ngân hàng Trung ương Úc năm một nghìn chín trăm chín mươi tám, chỉ sau vài tháng, đồng baht mất khoảng một nửa giá trị so với đô la. Giá cổ phiếu Thái đã giảm hơn sáu mươi phần trăm so với đỉnh đầu năm một nghìn chín trăm chín mươi bốn. Kinh tế giảm hai phẩy tám phần trăm trong năm một nghìn chín trăm chín mươi bảy, rồi giảm tiếp bảy phẩy sáu phần trăm trong năm một nghìn chín trăm chín mươi tám.'}, {'k': 'call', 'cap': ('"BỐ TÔI MẤT VIỆC', 'NỢ ĐÔ LA THÌ TĂNG GẤP ĐÔI"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'call': {'ten': 'Somchai', 'phu': 'Gọi video từ Bangkok', 'mau': (239, 68, 68), 'loi': ['Bố tôi làm cho một công ty xây dựng', 'Công ty vay đô la, baht mất giá là sập']}, 'say': 'Somchai gọi video, giọng chậm hẳn lại. Bố anh ấy hồi đó làm cho một công ty xây dựng ở Bangkok, công ty vay đô la để xây chung cư. Baht mất một nửa giá trị, món nợ tính ra tiền baht gần như tăng gấp đôi. Công ty đóng cửa, bố anh ấy mất việc, căn nhà trả góp cũng không giữ được. Cả nhà làm lại từ đầu.'}, {'k': 'text', 'cap': ('TĂNG NHANH BẰNG TIỀN VAY', 'THÌ NGÃ CŨNG RẤT ĐAU'), 'cols': ((255, 255, 255), (239, 68, 68)), 'anh': 'File:Bangkok_-_City_skyline_at_sunset.JPG', 'say': 'Anh chị thấy đấy, khi kinh tế tăng quá nóng bằng tiền đi vay, nhất là vay ngoại tệ ngắn hạn đổ vào bất động sản, chỉ cần dòng tiền quay đầu một lần là mọi thứ sụp rất nhanh. Nhưng cú sập chưa phải phần đáng sợ nhất. Đáng sợ nhất là chuyện xảy ra trong hai mươi lăm năm sau đó.'}, {'k': 'bars', 'ch': 'Chương 3 – Kẹt ở hai phần trăm', 'anh': 'File:Twilight_over_the_modern_city_skyline_in_Ratchadamri_district,_Bangkok,_Thailand,_July_2019_-_Flickr_-_sergei.gussev.jpg', 'cap': ('DỰ BÁO TĂNG TRƯỞNG 2026', 'IMF THÁNG 10/2026'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'bars': [('Việt Nam', 8.4, (34, 197, 94), '8,4%'), ('Malaysia', 5.2, (255, 196, 0), '5,2%'), ('Thái Lan', 2.1, (239, 68, 68), '2,1%')], 'say': 'Thái Lan hồi phục sau khủng hoảng, nhưng không chạy nhanh lại được nữa. Báo cáo tháng mười năm nay của Quỹ Tiền tệ Quốc tế dự báo: Việt Nam tăng tám phẩy bốn phần trăm, Malaysia năm phẩy hai phần trăm, còn Thái Lan chỉ hai phẩy một phần trăm, thuộc nhóm chậm nhất Đông Nam Á. Báo chí khu vực gọi Thái Lan là người bệnh của châu Á.'}, {'k': 'bignum', 'anh': 'File:Bangkok,_Thailand,_Benjakitti_Park,_2024.jpg', 'cap': ('NỢ CỦA CÁC GIA ĐÌNH THÁI', 'BẰNG 86,7% GDP'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'value': 86.7, 'fmt': '{:,.1f}', 'unit': '%', 'top': 'NỢ HỘ GIA ĐÌNH / GDP', 'sub': 'Thái Lan quý 4/2025, SCB EIC', 'col': (239, 68, 68), 'say': 'Và đây là cú lật thứ hai. Cuối năm hai nghìn không trăm hai mươi lăm, tổng nợ của các hộ gia đình Thái Lan bằng tám mươi sáu phẩy bảy phần trăm GDP cả năm, theo trung tâm nghiên cứu kinh tế SCB E I C. Đáng lo hơn, phần nợ tăng thêm chủ yếu là vay tiêu dùng, tức là vay để trang trải chi tiêu hằng ngày, không phải để làm ăn.'}, {'k': 'giay', 'cap': ('BẢNG LƯƠNG CỦA SOMCHAI', 'MỘT NỬA ĐÃ LÀ TRẢ NỢ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'BẢNG LƯƠNG THÁNG 10 – SOMCHAI', 'so': 'Em giả định để minh hoạ, đơn vị baht', 'dau': 'ĐÃ TRỪ', 'dieu': [('Lương thực nhận: 25.000 baht', '25.000'), ('Trả góp xe bán tải: 8.000 baht', '8.000'), ('Thẻ tín dụng: 4.500 baht', '4.500'), ('Trả nợ chiếm bao nhiêu phần lương', '50%')]}, 'say': 'Somchai chụp bảng lương gửi anh Hưng, số này em giả định để minh hoạ. Lương thực nhận hai mươi lăm nghìn baht. Trả góp xe bán tải tám nghìn. Thẻ tín dụng bốn nghìn rưỡi. Đúng một nửa tiền lương đã đi trả nợ trước khi kịp mua bất cứ thứ gì. Phần còn lại lo ăn ở, và gửi về cho bố mẹ đã già.'}, {'k': 'cards', 'anh': 'File:Bangkok_Skyline_from_Movenpick_Hotel,_Asok,_Bangkok_at_night.jpg', 'cap': ('GIÀ TRƯỚC KHI GIÀU', 'THE NATION 9/2025'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('Hơn 20%', 'Dân số từ 60 tuổi, năm 2023', 'Đã thành xã hội già'), ('28%', 'Dự báo cho năm 2033', 'Già đi rất nhanh'), ('Gần 1/2', 'Người già không có tiết kiệm', 'Con cái phải gánh')], 'say': 'Vì sao phải gửi tiền về cho bố mẹ? Vì Thái Lan đã già trước khi kịp giàu. Từ năm hai nghìn không trăm hai mươi ba, hơn hai mươi phần trăm dân số Thái từ sáu mươi tuổi trở lên, và được dự báo lên hai mươi tám phần trăm vào năm hai nghìn không trăm ba mươi ba. Báo The Nation dẫn ý kiến chuyên gia: gần một nửa người cao tuổi Thái không có tiền tiết kiệm. Người trẻ vừa trả nợ của mình, vừa gánh tuổi già của cha mẹ.'}, {'k': 'giay', 'ch': 'Chương 4 – Việt Nam có đang đi lại con đường đó?', 'cap': ('ĐỒNG HỒ DÂN SỐ VIỆT NAM', 'CÒN KHOẢNG 10 NĂM'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'DỰ BÁO DÂN SỐ VIỆT NAM 2024–2074', 'so': 'Cục Thống kê – Quỹ Dân số Liên hợp quốc', 'dau': 'DỰ BÁO', 'dieu': [('Người từ 60 tuổi năm 2024: 14,2 triệu', '14,2 TR'), ('Năm Việt Nam thành nước dân số già', '2034'), ('Dân số vàng kết thúc, sớm hơn 3 năm', '2036')]}, 'say': 'Giờ quay về Việt Nam. Theo báo cáo dự báo dân số do Cục Thống kê làm cùng Quỹ Dân số Liên hợp quốc, năm hai nghìn không trăm hai mươi bốn cả nước có khoảng mười bốn phẩy hai triệu người từ sáu mươi tuổi trở lên. Tới năm hai nghìn không trăm ba mươi bốn, Việt Nam chính thức thành nước có dân số già. Thời kỳ dân số vàng, lúc người đi làm đông hơn hẳn người phụ thuộc, dự kiến kết thúc khoảng năm hai nghìn không trăm ba mươi sáu, sớm hơn ba năm so với dự báo cũ.'}, {'k': 'checklist', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('VIỆT NAM GIỐNG THÁI LAN', 'Ở 3 ĐIỂM'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'items': [('Tăng nhanh nhờ nhà máy FDI', (255, 196, 0)), ('Xuất khẩu là động cơ chính', (255, 196, 0)), ('Dân số vàng sắp hết', (239, 68, 68))], 'say': 'Đặt hai nước cạnh nhau, có ba điểm giống đến giật mình. Một: tăng trưởng nhanh nhờ nhà máy nước ngoài. Hai: xuất khẩu là động cơ chính. Ba: cửa sổ dân số vàng đang khép lại. Khác biệt là Việt Nam còn khoảng mười năm, và mười năm đó dùng thế nào sẽ quyết định mình thành ai.'}, {'k': 'bars', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('BAO NHIÊU NĂM TỚI NGƯỠNG GIÀU?', 'EM TỰ TÍNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'bars': [('Tăng 7% mỗi năm', 15.7, (34, 197, 94), '16 năm'), ('Tăng 5% mỗi năm', 21.8, (255, 196, 0), '22 năm'), ('Tăng 2% như Thái', 53.6, (239, 68, 68), '54 năm')], 'say': 'Em làm một phép tính. Từ bốn nghìn chín trăm bảy mươi đô la, nếu thu nhập bình quân tính bằng đô la tăng đều bảy phần trăm mỗi năm, Việt Nam cần khoảng mười sáu năm để chạm ngưỡng nước giàu. Tức là quanh năm hai nghìn không trăm bốn mươi mốt. Nếu chỉ tăng năm phần trăm, cần khoảng hai mươi hai năm, lỡ mục tiêu năm hai nghìn không trăm bốn mươi lăm. Nếu chậm lại hai phần trăm như Thái Lan bây giờ, cần hơn năm mươi năm. Em giả định ngưỡng đứng yên, cách tính có trong mô tả.'}, {'k': 'cards', 'ch': 'Chương 5 – Con đường của Hàn Quốc', 'anh': 'ov:Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('PHƯƠNG ÁN KHÁC', 'HÀN QUỐC 1970 TỚI 1996'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('7 đến 10%', 'Mỗi năm, từ 1970 tới 1996', 'Gần 30 năm liền'), ('1996', 'Hàn Quốc vào khối OECD', 'Bước qua ngưỡng giàu'), ('2045', 'Mục tiêu của Việt Nam', 'Còn 19 năm')], 'say': 'Có một con đường khác. Hàn Quốc tăng trưởng bảy đến mười phần trăm gần như mỗi năm, từ năm một nghìn chín trăm bảy mươi đến năm một nghìn chín trăm chín mươi sáu. Cũng trong năm một nghìn chín trăm chín mươi sáu, họ được nhận vào khối các nước phát triển OECD. Khác biệt không nằm ở tốc độ một vài năm, mà ở chỗ họ giữ được tốc độ đó gần ba mươi năm, đi từ lắp ráp lên làm công nghệ.'}, {'k': 'text', 'cap': ('TRỞ THÀNH NƯỚC NÀO', 'NẰM Ở 10 NĂM TỚI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'say': 'Nhưng với mỗi gia đình, câu hỏi nhỏ hơn và gần hơn. Nhà nào vay để tiêu, nhà đó đi theo đường của Somchai. Nhà nào dùng những năm thu nhập tăng nhanh để học thêm, để dành và tránh nợ tiêu dùng, nhà đó đi đường thứ hai, dù đất nước đi đường nào.'}, {'k': 'chat', 'ch': 'Chương 6 – Kế hoạch của nhà anh Hưng', 'cap': ('KẾ HOẠCH CỦA NHÀ HƯNG', 'TRƯỚC KHI DÂN SỐ VÀNG HẾT'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Vợ', 'tv': 'Đang hoạt động', 'gio': '22:40', 'mau': (34, 197, 94), 'msgs': [('me', 'Thôi, anh chưa đổi xe trả góp nữa'), ('Vợ', 'Ừ, tiền trả nợ đừng quá 1/3 lương'), ('me', 'Phần lương tăng thêm, mình để dành cho lúc bố mẹ già'), ('Vợ', 'Còn anh đi học tiếng Nhật cho lên tổ trưởng')]}, 'say': 'Anh Hưng nhắn cho vợ: thôi, anh chưa đổi xe trả góp nữa. Vợ anh đáp: ừ, tiền trả nợ đừng quá ba mươi ba phần trăm tiền lương. Anh nhắn tiếp: phần lương tăng thêm, mình để riêng cho lúc bố mẹ già. Vợ anh thêm: còn anh đi học tiếng Nhật cho lên tổ trưởng. Thu nhập tăng nhanh nhất vẫn đến từ tay nghề.'}, {'k': 'checklist', 'anh': 'ov:Hanoi apartment buildings||Hanoi apartment buildings', 'cap': ('PHÉP THỬ CỦA ANH CHỊ', 'TRẢ NỢ CHIẾM BAO NHIÊU LƯƠNG?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Dưới 30%: còn thở được', (34, 197, 94)), ('30 đến 50%: bắt đầu căng', (255, 196, 0)), ('Trên 50%: như Somchai', (239, 68, 68))], 'say': 'Và đây là phép thử anh chị tự làm được tối nay. Cộng mọi khoản trả nợ mỗi tháng, trả góp nhà, xe, điện thoại, thẻ tín dụng, rồi chia cho tổng thu nhập. Dưới ba mươi phần trăm thì còn thở được. Từ ba mươi đến năm mươi phần trăm là bắt đầu căng. Trên năm mươi phần trăm, nhà mình đang sống giống Somchai. Đây là mốc em đặt để tự soi, không phải quy định.'}, {'k': 'checklist', 'ch': 'Chương 7 – Nhà đầu tư nên theo dõi gì?', 'anh': 'ov:Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('3 CON SỐ CẦN THEO DÕI', 'ĐỂ BIẾT VIỆT NAM ĐI ĐƯỜNG NÀO'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Tăng trưởng có giữ trên 5,5%?', (34, 197, 94)), ('Nợ vay tiêu dùng tăng nhanh?', (255, 196, 0)), ('Doanh nghiệp Việt có lớn lên?', (34, 197, 94))], 'say': 'Với anh chị có thêm khoản đầu tư, em gợi ý theo dõi ba điều. Một: thu nhập có giữ được mức tăng trên năm phẩy năm phần trăm qua nhiều năm không, đó là tốc độ cần để kịp năm hai nghìn không trăm bốn mươi lăm. Hai: nợ vay tiêu dùng có tăng nhanh hơn thu nhập không. Ba: lợi nhuận doanh nghiệp Việt có lớn lên cùng nền kinh tế không. Lợi nhuận từng quý của hơn bốn trăm mã có miễn phí trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'chat', 'ch': 'Kết – Tin nhắn từ Bangkok', 'cap': ('"ĐỪNG GIÀ', 'TRƯỚC KHI GIÀU NHƯ BỌN TÔI"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Somchai', 'tv': 'Đang hoạt động', 'gio': '23:30', 'mau': (56, 189, 248), 'msgs': [('Somchai', 'Nước ông đang chạy nhanh như nước tôi ngày xưa'), ('Somchai', 'Đừng già trước khi giàu như bọn tôi nhé'), ('me', 'Cảm ơn ông. Tôi bắt đầu từ nhà mình trước')]}, 'say': 'Gần nửa đêm, Somchai nhắn thêm: nước Việt Nam đang chạy nhanh như Thái Lan ngày xưa, đừng già trước khi giàu nhé. Anh Hưng trả lời: cảm ơn, mình bắt đầu từ nhà mình trước. Tăng trưởng tám đến chín phần trăm là cơ hội của cả một thế hệ. Nhưng Thái Lan cho thấy, cơ hội đó có hạn dùng.'}, {'k': 'end', 'cap': ('HÀN QUỐC HAY THÁI LAN', 'THỨ HAI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị nghĩ sao: Việt Nam sẽ thành Hàn Quốc, hay thành Thái Lan thứ hai? Và khoản trả nợ mỗi tháng của nhà mình đang chiếm bao nhiêu phần thu nhập? Kể cho em và mọi người ở phần bình luận nhé. Nếu thấy video hữu ích, anh chị đăng ký kênh để xem những câu hỏi lớn tiếp theo.'}]
META = {'CH1811TL': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Câu hỏi lớn', 'ngay': '2026-11-18', 'gio_goi_y': '12:00', 'gio': '12:00', 'nhac': 'lofi', 'tieu_de': 'Việt Nam Có Thành Thái Lan Thứ Hai? Từng Tăng 13,3% Một Năm, Giờ Kẹt Ở 2% Và Nợ 86,7% GDP', 'title': 'Việt Nam Có Thành Thái Lan Thứ Hai? Từng Tăng 13,3% Một Năm, Giờ Kẹt Ở 2% Và Nợ 86,7% GDP', 'mo_ta': 'Năm 1988 Thái Lan tăng trưởng 13,3%, nhanh hơn cả Việt Nam bây giờ. Gần 40 năm sau, họ vẫn chưa thành nước giàu: tăng trưởng còn khoảng 2%, nợ hộ gia đình bằng 86,7% GDP, hơn 20% dân số đã từ 60 tuổi. Việt Nam đang tăng 8–10% và có 3 điểm giống Thái Lan. Câu chuyện của anh Hưng và người bạn Thái Somchai, cùng phép thử cho chính gia đình anh chị.\n\nNguồn số liệu:\n• Tiền Phong 9/7/2026 (số Ngân hàng Thế giới): Thái Lan GDP +13,3% năm 1988, trên 10% liên tục 1987–1990; 1997 −2,8%; 1998 −7,6%; thả nổi baht 2/7/1997; GNI bình quân đầu người 2025: Thái Lan khoảng 7.690 USD, Việt Nam 4.970 USD; ngưỡng thu nhập cao 14.375 USD; Hàn Quốc tăng 7–10%/năm giai đoạn 1970–1996, vào OECD 1996\n• Ngân hàng Trung ương Úc (RBA), RDP 9805 (1998): baht mất khoảng một nửa giá trị so với USD tới đáy tháng 1/1998; cổ phiếu Thái giảm hơn 60% từ đỉnh đầu 1994\n• IMF, Triển vọng kinh tế thế giới 10/2026 (TNGlobal 13/10/2026): tăng trưởng 2026 Việt Nam 8,4%, Malaysia 5,2%, Thái Lan 2,1%\n• SCB EIC (The Nation 15/4/2026): nợ hộ gia đình Thái Lan quý 4/2025 là 12,72 nghìn tỷ baht, 86,7% GDP, tăng chủ yếu do vay tiêu dùng cá nhân\n• The Nation 28/9/2025: hơn 20% dân số Thái từ 60 tuổi (từ 2023), dự báo 28% năm 2033; gần một nửa người cao tuổi không có tiết kiệm\n• Cục Thống kê – UNFPA, Dự báo dân số 2024–2074 (Tuổi Trẻ 27/1/2026): 14,2 triệu người từ 60 tuổi năm 2024; Việt Nam thành dân số già năm 2034; dân số vàng kết thúc khoảng 2036\n• Tổng cục Thống kê (WiData): GDP Việt Nam 2025 +8,02%; quý 3/2026 +9,95%\n• Tự tính: 7.690/4.970 = 1,55 (Thái Lan cao hơn khoảng 55%). Số năm tới ngưỡng = ln(14.375/4.970)/ln(1+g), giả định ngưỡng đứng yên: g=7% → khoảng 16 năm; g=5% → 22 năm; g=2% → 54 năm; kịp 2045 cần g khoảng 5,5%\n• Bảng lương của Somchai là giả định minh hoạ (25.000 baht, trả góp 8.000 + thẻ 4.500 = 50% lương)\n\nTra lợi nhuận từng quý 400+ mã: https://chungkhoanhuynguyen.com\nCần trao đổi riêng: Zalo 0365.188.286\n\nNhân vật anh Hưng, vợ anh và Somchai là hư cấu; số liệu là thật.\nChia sẻ góc nhìn, không phải khuyến nghị mua bán.', 'tags': ['Việt Nam và Thái Lan', 'bẫy thu nhập trung bình', 'kinh tế Thái Lan', 'khủng hoảng 1997', 'nợ hộ gia đình', 'già hóa dân số', 'GDP Việt Nam', 'kinh tế Việt Nam', 'vĩ mô'], 'bia_hook': ['THÁI LAN 13,3%', 'GIỜ CÒN 2%???'], 'badge': 'VIỆT NAM CÓ THEO?', 'bia_anh': 'Ho Chi Minh City skyline night||Hanoi skyline night', 'bia_hook_b': ['NỢ 86,7% GDP', 'GIÀ TRƯỚC GIÀU'], 'badge_b': 'THÁI LAN · SCB EIC', 'bia_hook_c': ['HÀN QUỐC', 'HAY THÁI LAN?'], 'badge_c': 'CÂU HỎI LỚN', 'reel_hook': 'THÁI LAN TỪNG TĂNG 13%|VIỆT NAM CÓ ĐI VẾT XE ĐỔ???', 'fb_post': 'Việt Nam có thành Thái Lan thứ hai? 🇹🇭\n\n👉 Thái Lan năm 1988 tăng 13,3%, nay chỉ khoảng 2%\n👉 Nợ hộ gia đình Thái: 86,7% GDP\n👉 Việt Nam thành dân số già năm 2034, dân số vàng hết khoảng 2036\n\nKhoản trả nợ mỗi tháng nhà anh chị chiếm bao nhiêu phần thu nhập?\n🎬 Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Con hổ từng chạy nhanh nhất châu Á', 'Chương 2 – Ngày 2 tháng 7 năm 1997', 'Chương 3 – Kẹt ở hai phần trăm', 'Chương 4 – Việt Nam có đang đi lại con đường đó?', 'Chương 5 – Con đường của Hàn Quốc', 'Chương 6 – Kế hoạch của nhà anh Hưng', 'Chương 7 – Nhà đầu tư nên theo dõi gì?', 'Kết – Tin nhắn từ Bangkok']}}
